const CLASS_NAME='teriash-galaxy';
let active=true;
function apply(){
 if(!document.documentElement)return;
 document.documentElement.classList.toggle(CLASS_NAME,active);
 if(!document.getElementById(STYLE_ID)){
   const style=document.createElement('style');style.id=STYLE_ID;
   style.textContent=CSS_CONTENT;
   (document.head||document.documentElement).appendChild(style);
 }
}
function init(){apply();}
init();
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});
window.GalaxyTheme=Object.freeze({
 version:'3.0.0',
 enable(){active=true;apply();},
 disable(){active=false;apply();},
 get enabled(){return active;},
 debug(){return {enabled:active,styleFound:!!document.getElementById(STYLE_ID),styleLength:document.getElementById(STYLE_ID)?.textContent.length||0,uiElements:document.querySelectorAll('.layer.interface-layer').length};}
});
